// src/pages/Result.js

import React from "react";
import { useLocation } from "react-router-dom";

const Result = () => {
  const location = useLocation();
  const { style, occasion, outfit } = location.state || {};

  return (
    <div style={{ padding: "30px", maxWidth: "600px", margin: "0 auto" }}>
      <h2>💃 Your Outfit Suggestion</h2>

      {style && occasion && outfit ? (
        <div style={{ marginTop: "20px", fontSize: "18px", lineHeight: "1.6" }}>
          <p><strong>Style:</strong> {style}</p>
          <p><strong>Occasion:</strong> {occasion}</p>
          <p><strong>Outfit:</strong> {outfit}</p>
        </div>
      ) : (
        <p>Please complete the quiz first.</p>
      )}
    </div>
  );
};

export default Result;
